# Let's test different patch types in different corners to find the trigger
# The patch is 3-5 pixels wide, 1 pixel in from corner

def test_patch(patch_type, corner, patch_size=4):
    """Test a patch on a clean image and see what class it predicts"""
    # Use first clean image
    x = x_clean[0:1].clone().float()  # (1, 3, 32, 32)

    # Apply patch
    if corner == 'top_left':
        h_start, w_start = 1, 1
    elif corner == 'top_right':
        h_start, w_start = 1, 32 - 1 - patch_size
    elif corner == 'bottom_left':
        h_start, w_start = 32 - 1 - patch_size, 1
    elif corner == 'bottom_right':
        h_start, w_start = 32 - 1 - patch_size, 32 - 1 - patch_size

    if patch_type == 'white':
        patch_val = 255
        x[0, :, h_start:h_start+patch_size, w_start:w_start+patch_size] = patch_val
    elif patch_type == 'black':
        patch_val = 0
        x[0, :, h_start:h_start+patch_size, w_start:w_start+patch_size] = patch_val
    elif patch_type == 'checkerboard':
        for i in range(patch_size):
            for j in range(patch_size):
                val = 255 if (i+j) % 2 == 0 else 0
                x[0, :, h_start+i, w_start+j] = val
    elif patch_type == 'noise':
        noise = torch.randint(0, 256, (3, patch_size, patch_size))
        x[0, :, h_start:h_start+patch_size, w_start:w_start+patch_size] = noise

    logits = forward(W, x.to(torch.uint8))
    pred = logits.argmax(dim=1).item()
    return pred, logits[0].detach().cpu().numpy()

# Test various patches
patch_types = ['white', 'black', 'checkerboard', 'noise']
corners = ['top_left', 'top_right', 'bottom_left', 'bottom_right']
patch_sizes = [3, 4, 5]

results = {}
for ps in patch_sizes:
    for pt in patch_types:
        for c in corners:
            pred, logits = test_patch(pt, c, ps)
            results[(pt, c, ps)] = (pred, logits)
            print(f"Patch: {pt}, Corner: {c}, Size: {ps} -> Class: {pred} ({CLASSES[pred]})")

